 -{[DEF}]={[DFE}]=&{[EPF]}+{[FPD]}+{[DPE]} 
            =&{[ABPC]}+{[BCPA]}+{[CAPB]} 
            =&\{ {[BPA]}+{[APC]} \}+\{ {[ABC]}-{[APC]} \} + \{ {[ABC]}-{[BPA]} \} 
