\end{align*}
Substituting back we have either  $z^{840} = -1$  or  $z^{600} = 1$ . Clearly these do not overlap, so we have  $84 0 + 600 = 1\boxed{440}$  solutions.

Let  $a_n, b_n, c_n, d_n, e_n, f_n, g_n$  be respectively the number of distinct sequences that start at the vertex  $S$  and end at the vertices  $S, P_1, P_2, P_3, E, P_4, P_5$  after  $n$  jumps.
Clearly,
\begin{align*}
a_n = b_{n-1}+g_{n-1}, &\qquad b_n = a_{n-1} + c_{n-1} 
c_n = b_{n-1} + d_{n-1}, &\qquad d_n = c_{n-1} 
f_n = g_{n-1} &\qquad g_n = a_{n-1} + f_{n-1} 
\end{align*}
and  $e_n = d_{n-1} + f_{n-1}$ . From these, we deduce
\begin{align*}
a_n = b_{n-1} + f_n, \qquad b_n = a_{n-1} + d_n
\end{align*}
and hence 
\begin{align}
a_n + b_n &= (a_{n-1} + b_{n-1}) + (f_n+d_n) \nonumber 
&=  (a_{n-1} + b_{n-1}) + e_{n+1} \label{AIMEfrog1}
\end{align}
Also, 
\begin{align*}
f_{n+1} - f_{n-1} &= g_n - f_{n-1} = a_{n-1}
d_{n+1} - d_{n-1} &= c_n - d_{n-1} = b_{n-1}
\end{align*}
Hence
\begin{align}
e_{n+2} - e_n = a_{n-1}+b_{n-1} \label{AIMEfrog2}
\end{align}
From \eqref{AIMEfrog1} and \eqref{AIMEfrog2} we obtain the recurrence for  $e_n$  as 
\begin{align}
e_{n+3} = e_{n+2}+2e_{n+1}-e_n
\end{align}
It is not difficult to see that  $e_1 = 0, e_2 = 0$  and  $e_3 = 1$ . Hence
\begin{align*}
e_4 = 1, e_5 = 3, \, e_6 = 4, \, e_7 =9 ,\, e_8 =14 \,
e_9 = 28, \, e_{10} = 47, \, e_{11} = 89,\, e_{12} = 155 
\end{align*}
Thus the number of distinct sequences of jumps of no more than 12 jumps that end at  $E$  is   $$ 0+0+1+1+3+4+9+14+28+47+89+155 = 351 $$

Okay so we want,
\begin{align*}
3^n \equiv 1 \pmod{11^2 \cdot 13^2}.
\end{align*}
First off we want  $\nu_{11}(3^n - 1) \geq 2$ . Note that  $3^5 - 1 \equiv 0 \pmod{11}$  so  $n = 5k$  and it is easily checked  $k \geq 1 $  all work. Next we need  $\nu_{13}(3^n - 1) \geq 2$ . Note that  $3^3 - 1 \equiv 0 \pmod{13}$  so that  $n = 3m$ . Moreover we have,
\begin{align*}
\nu_{13}(3^{3m} - 1) = \nu_{13}(26) + \nu_{13}(m)
\end{align*}
so we need  $13 \mid m$  or  $ n \equiv 0 \pmod{39}$ . Extract  $39 \cdot 5 = \boxed{195}$ .

