\begin{align*}
	\sum_{cyc}\frac{ab}{a+b}&=\frac{2}{3abc}\left(\sum_{cyc}\frac{ab}{a+b}\right) 
	&=\frac{2}{3}\sum_{cyc}\frac{c^2}{c^3(a+b)} 
	&\geq\frac{2}{3}\cdot\frac{(a+b+c)^2}{\sum_{sym}a^3b} 
	&\geq \frac{2(a+b+c)^2}{\sum_{sym}a^4+2\sum_{sym}a^3c} 
	&=\frac{2(a+b+c)^2}{2(a+b+c)(a^3+b^3+c^3)} 
	&=\frac{a+b+c}{a^3+b^3+c^3}
\end{align*}

By Cauchy-Schwarz, then
\begin{align*}
\frac {ab}{a + b} + \frac {bc} {b + c} + \frac {ca} {c + a} &= \frac{1}{\tfrac{1}{a} + \tfrac{1}{b}} + \frac {1} {\tfrac{1}{b} + \tfrac{1}{c}} + \frac {1} {\tfrac{1}{c} + \tfrac{1}{a}} 
&\geq \frac{(1+1+1)^3}{\tfrac{2}{a}+\tfrac{2}{b}+\tfrac{2}{c}} = \dfrac{9abc}{2(ab+bc+ca)} = \dfrac{3}{ab+bc+ca}.
\end{align*}
Expanding, then:
\begin{align*}
\dfrac{3}{ab+bc+ca} \geq \dfrac{a+b+c} {a^3 + b^3 + c^3} \iff 3a^3+3b^3+3c^3 \geq a^2b + b^2c + c^2a + ab^2 + b^2c + c^2a + 3abc.
\end{align*}
Nicely, this finishes via Muirhead's Inequality, as desired.

