& =\underbrace{\left(  1+2+\cdots+n\right)  }_{=\dfrac{n\left(  n+1\right)
}{2}}c+\underbrace{\left(  1^{2}+2^{2}+\cdots+n^{2}\right)  }_{=\dfrac
{n\left(  n+1\right)  \left(  2n+1\right)  }{6}}d
