\end{cases}\] $A$  increases every minute.  $A\leq \sum_i \sum_{j<i} 2^{j-1} = \sum_i 2^{i-1}-1 = 2^n-1-n = 2^n - (n+1)$ . Hence, the maximum number of euros is  $2^n-(n+1)$ . This is achieved when the initial configuration is  $C_1C_2C_3\dots C_{n}$ .

[asy]
size(8cm);
pair A=dir(150); pair B=dir(30); pair C=dir(90); pair P=dir(-50); pair M=midpoint(A--B); pair Q=1/3*P+2/3*C; pair N=extension(M, Q, P, P+dir(90)*(A-B));

draw(unitcircle);
draw(circumcircle(A, B, N), dotted);
draw(A--B--C--cycle); draw(M--N); draw(P--N); draw(C--P); draw(C--M);

string[] names = {" $A$ ", " $B$ ", " $C$ ", " $P$ ", " $M$ ", " $Q$ ", " $N$ "};
pair[] pts = {A, B, C, P, M, Q, N};
