\begin{lemma}
    \[ \sum_{j = m}^{2m} \frac{\binom{j}{m}}{2^j} = 1.\]
\end{lemma}
\begin{proof}
    It follows from Pascal's identity:
    \begin{align*}
    S_m = \sum_{j = m}^{2m} \frac{\binom{j}{m}}{2^j} & = \sum_{j = m}^{2m} \frac{\binom{j-1}{m}}{2^j} + \sum_{j =m}^{2m} \frac{\binom{j-1}{m-1}}{2^j} 
    & = \frac{1}{2} \left ( \sum_{j = m}^{2m-1} \frac{\binom{j}{m}}{2^j} \right ) + \frac{1}{2} \left ( \sum_{j = m-1}^{2m-1} \frac{\binom{j}{m-1}}{2^j} \right ) 
    & = \frac{1}{2} \left ( S_m - \frac{\binom{2m}{m}}{2^{2m}} \right ) + \frac{1}{2} \left ( S_{m-1} + \frac{\binom{2m-1}{m-1}}{2^{2m-1}} \right ) 
    & = \frac{S_m + S_{m-1}}{2} \implies S_m = S_{m-1}.
    \end{align*}
    Thus,  $S_m = ... = S_1 = 1$ . We have proven the lemma. 
\end{proof}

Let  $A(n, k)$  be the probability that after  $k-1$  you are still have less than  $n$  points but at the  $k$ th move you have at least  $n$  points Let  $B(n, k)$  be the probability that after  $k$  turns, you still have less than  $n$  points. 
\begin{align*}
    A(n, k) & = \sum_{\substack{x_1 + ... + x_{k-1} \leq n-1  x_1, ..., x_{k-1} \geq 1}} 2^{-\sum x_i} \cdot 2^{1 - (n - \sum x_i)} 
    & = 2^{1-n} \sum_{M = k-1}^{n-1} \binom{M-1}{k-2} = 2^{1-n} \binom{n-1}{k-1}. 
    B(n, k) & = \sum_{\substack{x_1 + ... + x_k \leq n-1  x_1, ..., x_k \geq 1}} 2^{-x_1 - ... - x_k} = \sum_{M = k}^{n-1} 2^{-M} \binom{M-1}{k-1}  
\end{align*}
Suppose Ann needs  $n+1$  to win and Drew needs  $n$  to win. So, the probability that Ann wins is
\begin{align*}
    2^{-n} + \sum_{k = 2}^n A(n+1, k) B(n, k-1) & = 2^{-n} + \sum_{k = 2}^n 2^{-n} \binom{n}{k-1} \sum_{M = k-1}^{n-1} 2^{-M} \binom{M-1}{k-2} 
    & = 2^{-n} + \sum_{M = 1}^{n-1} 2^{-(n+M)} \sum_{k = 2}^{M+1} \binom{n}{k-1} \binom{M-1}{M-k+1} 
    & = 2^{-n} + \sum_{M = 1}^{n-1} 2^{-(n+M)} \binom{n+M-1}{n-1} 
    & = \sum_{M = 0}^{n-1} 2^{-(n+M)} \binom{(n+M)-1}{n-1} 
    & = \frac{1}{2} \sum_{j = n-1}^{2(n-1)} \frac{\binom{j}{n-1}}{2^j} = \frac{1}{2}. 
\end{align*}
So, Alice would need to have  $2^{2018} + 1 \equiv 5 \pmod{2018}$ .

